-- Migración 2 (parte) · geo_semilla_paises_1 — países A–L de supabase/seed/geo.sql
-- (pnpm geo:build), filas sin cambios; separado de `geo` por tamaño.

on conflict (iso2) do update set
  iso3 = excluded.iso3,
  numerico = excluded.numerico,
  nombre = excluded.nombre,
  nombre_normalizado = excluded.nombre_normalizado,
  alias = excluded.alias,
  continente = excluded.continente,
  subregion = excluded.subregion,
  con_geometria = excluded.con_geometria,
  lon = excluded.lon,
  lat = excluded.lat;

do $$ begin
  assert (select count(*) from public.paises) = 136, 'paises A–L: conteo inesperado';
end $$;
